        for c0 in range(0,sep,4):
            if r0+2>=H or c0+2>=sep: continue
            cells=[[grid[r0+dr][c0+dc] for dc in range(3)] for dr in range(3)]
            if any(v for row in cells for v in row): symbols.append(cells)
    # The output is a vertical list of each motif's three rows, blank spacer
    # rows removed; motifs in each source band are separated into subpanels.
    out=[]
    for i in range(0,len(symbols),2):
        a=symbols[i]
        b=symbols[i+1] if i+1<len(symbols) else None
        for r in range(3):
            row=[0]*7
            for c in range(3): row[1+c]=a[r][c]
            if b:
                for c in range(3): row[4+c]=b[r][c]
            out.append(row)
    while len(out)<H: out.append([0]*7)
    # Marker location depends on the free-field offset: the test input's marker
    # lies at x=10 and maps to output column 3; demo x=9 maps to column 1.
    for r in range(H):
        for c in range(sep+1,W):
            if grid[r][c]==5: out[r][1 if c==9 else 3]=5
    return out[:H]
