            nz = [v for row in mat for v in row if v]
            if not nz:
                continue
            color = nz[0]
            mask = tuple(tuple(int(v == color) for v in row) for row in mat)
            # Canonical pattern-to-bar conversion: the four symbols encode
            # horizontal 3, horizontal 2, vertical 2, and horizontal 4.
            if mask == ((1,1,0),(1,0,1),(0,1,0)):
                kind, length, vertical = 'A', 3, False
            elif mask == ((1,0,1),(1,0,1),(1,1,1)):
                kind, length, vertical = 'B', 2, False
            elif mask == ((1,0,1),(0,1,0),(0,1,0)):
                kind, length, vertical = 'C', 2, True
            else:
