    # the horizontal phase; each source band/column contributes a repeatable
    # position on the track.
    out = [[0] * 7 for _ in range(h)]
    out[0][max(0, min(6, marker))] = 5
    row = 1
    for rband, cband, color, kind, length, vertical in tiles:
