        elif kind == 'B':
            start = (marker + rband + 2*cband - 1) % 6
        elif kind == 'C':
            start = (marker + 2*rband + 3*cband - 1) % 7
        else:
            start = 1
        for j in range(length):
            rr = row + (j if vertical else 0)
            cc = start + (0 if vertical else j)
            if rr < h and cc < 7:
